@pytest.mark.filterwarnings("ignore::DeprecationWarning")
@pytest.mark.parametrize(
    "module_path",
    [
        pytest.param("pydantic.color"),
        pytest.param("pydantic_extra_types.color"),
    ],
)
def test_encode_color(module_path):
