def test_invalid_forward_ref_model():
    """
    This test is to document the fact that forward refs to a type with the same name as that of a field
    can cause problems, and to demonstrate a way to work around this.
    """
    # The problem:
    if sys.version_info >= (3, 11):
        # See PR #8243, this was a RecursionError raised by Python, but is now caught on the Pydantic side
        error = errors.PydanticUserError
    else:
        error = TypeError
    with pytest.raises(error):

        class M(BaseModel):
            B: ForwardRef('B') = Field(default=None)

    # The solution:
    class A(BaseModel):
        B: ForwardRef('__types["B"]') = Field()  # F821

    assert A.model_fields['B'].annotation == ForwardRef('__types["B"]')  # F821
    A.model_rebuild(raise_errors=False)
    assert A.model_fields['B'].annotation == ForwardRef('__types["B"]')  # F821

    class B(BaseModel):
        pass

    class C(BaseModel):
        pass

    assert not A.__pydantic_complete__
    types = {'B': B}
    A.model_rebuild(_types_namespace={'__types': types})
    assert A.__pydantic_complete__

    assert A(B=B()).B == B()
    with pytest.raises(ValidationError) as exc_info:
        A(B=C())
    # insert_assert(exc_info.value.errors(include_url=False))
    assert exc_info.value.errors(include_url=False) == [
        {
            'type': 'model_type',
            'loc': ('B',),
            'msg': 'Input should be a valid dictionary or instance of B',
            'input': C(),
            'ctx': {'class_name': 'B'},
        }
    ]


def test_incomplete_superclass() -> None:
    class MyModel(BaseModel):
        sub_model: 'SubModel'

    assert not MyModel.__pydantic_fields_complete__
    assert not MyModel.__pydantic_complete__

    with pytest.raises(PydanticUndefinedAnnotation, match="name 'SubModel' is not defined"):
        MyModel.model_rebuild()

    class SubModel(MyModel):
        pass

    # SubModel is complete because it reinterprets the superclass's fields and finds 'SubModel' to match itself
    assert SubModel.__pydantic_fields_complete__
    assert SubModel.__pydantic_complete__

    # MyModel is still incomplete until it's rebuilt
    assert not MyModel.__pydantic_fields_complete__
    assert not MyModel.__pydantic_complete__

    MyModel.model_rebuild()

    assert MyModel.__pydantic_fields_complete__
    assert MyModel.__pydantic_complete__


