def test_none_discriminated_union() -> None:
    """https://github.com/pydantic/pydantic/issues/13660"""

    class A(BaseModel):
        field: Literal['A'] = 'A'

    class B(BaseModel):
        field: None = None

    class Model(BaseModel):
