import pytest
from pydantic_core import PydanticUndefined

from pydantic import BaseModel, ConfigDict, PrivateAttr, PydanticUserError, computed_field
from pydantic.fields import ModelPrivateAttr


def test_private_attribute():
    default = {'a': {}}

    class Model(BaseModel):
        _foo = PrivateAttr(default)

    assert set(Model.__private_attributes__) == {'_foo'}

    m = Model()
    assert m._foo == default
    assert m._foo is not default
    assert m._foo['a'] is not default['a']

    m._foo = None
    assert m._foo is None

    assert m.model_dump() == {}
    assert m.__dict__ == {}


def test_private_attribute_double_leading_underscore():
    default = {'a': {}}

    class Model(BaseModel):
        __foo = PrivateAttr(default)

    assert set(Model.__private_attributes__) == {'_Model__foo'}

    m = Model()

    with pytest.raises(AttributeError, match='__foo'):
        m.__foo
    assert m._Model__foo == default
    assert m._Model__foo is not default
    assert m._Model__foo['a'] is not default['a']

    m._Model__foo = None
    assert m._Model__foo is None

    assert m.model_dump() == {}
    assert m.__dict__ == {}


def test_private_attribute_nested():
    class SubModel(BaseModel):
        _foo = PrivateAttr(42)
        x: int

    class Model(BaseModel):
        y: int
        sub: SubModel

    m = Model(y=1, sub={'x': 2})
    assert m.sub._foo == 42


def test_private_attribute_factory():
    default = {'a': {}}

    def factory() -> dict[str, dict]:
        return default

    class Model(BaseModel):
        _foo = PrivateAttr(default_factory=factory)

    assert Model.__private_attributes__ == {'_foo': PrivateAttr(default_factory=factory)}

    m = Model()
    assert m._foo == default
    assert m._foo is default
    assert m._foo['a'] is default['a']

    m._foo = None
    assert m._foo is None

    assert m.model_dump() == {}
    assert m.__dict__ == {}


def test_private_attribute_factory_uses_validated_data():
    def factory(data: dict[str, str]) -> str:
        return data['foo'] + data['bar']

    class Model(BaseModel):
        foo: str
        bar: str
        _foobaz = PrivateAttr(default_factory=factory)

    m = Model(foo='foo', bar='bar')
    assert m._foobaz == 'foobar'


def test_private_attribute_factory_uses_other_private_attribute():
    def factory(data: dict[str, str]) -> str:
        return data['foo'] + data['bar'] + data['_foobaz']

    class Model(BaseModel):
        foo: str
        bar: str
        _foobaz = PrivateAttr(default='foobaz')
        _foobazfoo = PrivateAttr(default_factory=factory)

    m = Model(foo='foo', bar='bar')
    assert m._foobaz == 'foobaz'
    assert m._foobazfoo == 'foobarfoobaz'


def test_private_attribute_factory_unset_private():
    def factory(data: dict[str, str]) -> str:
        return data['foo'] + data['bar'] + data['_foobazfoo']

    class Model(BaseModel):
        foo: str
        bar: str
        _foobaz = PrivateAttr(default_factory=factory)
        _foobazfoo = PrivateAttr(default='foobazfoo')

