def test_infinite_iterable_int():
    def int_iterable():
        i = 0
        while True:
            i += 1
            yield str(i)

    def str_iterable():
        while True:
            yield from 'foobarbaz'

    ta = TypeAdapter(Iterable[int])

    it = ta.validate_python(int_iterable())

    assert repr(it) == 'ValidatorIterator(index=0, schema=Some(Int(IntValidator { strict: false })))'

    output = []
    for i in it:
