def test_infinite_iterable_validate_first():
    def int_iterable():
        i = 0
        while True:
            i += 1
            yield str(i)

    def str_iterable():
        while True:
            yield from 'foobarbaz'

    class Model(BaseModel):
        it: Iterable[int]
        b: int

        @field_validator('it')
        @classmethod
        def infinite_first_int(cls, it):
            return itertools.chain([next(it)], it)

    m = Model(it=int_iterable(), b=3)

    assert m.b == 3
    assert m.it

    for i in m.it:
        assert i
        if i == 10:
