    ]


def test_namedtuple_mapping_input():
    class Map(Mapping):
        def __init__(self, **kwargs):
            self._d = kwargs

        def __iter__(self):
            return iter(self._d)

        def __len__(self) -> int:
            return len(self._d)

        def __getitem__(self, k, /):
            return self._d[k]

    class Point(NamedTuple):
        x: int
        y: int

    assert TypeAdapter(Point).validate_python(Map(x=1, y=2)) == Point(1, 2)


